import 'package:flutter/material.dart';

import '../../../core/data/app_history.dart';
import '../data/vsm_excel.dart';
import '../data/vsm_models.dart';

class VsmPage extends StatefulWidget { const VsmPage({super.key}); @override State<VsmPage> createState() => _VsmPageState(); }
class _VsmPageState extends State<VsmPage> {
  final _storage = VsmStorage(); final _name = TextEditingController(text: 'Yangi VSM'); final _demand = TextEditingController(); final _process = TextEditingController(); final _ct = TextEditingController(); final _co = TextEditingController(); final _uptime = TextEditingController(text: '100'); final _wip = TextEditingController(); final _lead = TextEditingController();
  bool _va = true; String _state = 'Current State'; List<VsmMap> _maps = []; List<VsmProcess> _processes = [];
  @override void initState(){super.initState();_load();}
  Future<void> _load() async {final v=await _storage.load();if(mounted)setState(()=>_maps=v);}
  void _add(){final ct=double.tryParse(_ct.text.replaceAll(',','.'));if(_process.text.trim().isEmpty||ct==null)return;setState(()=>_processes=[..._processes,VsmProcess(id:DateTime.now().microsecondsSinceEpoch.toString(),sequence:_processes.length+1,name:_process.text.trim(),cycleTimeSeconds:ct,changeoverSeconds:double.tryParse(_co.text.replaceAll(',','.'))??0,uptimePercent:double.tryParse(_uptime.text.replaceAll(',','.'))??100,wip:double.tryParse(_wip.text.replaceAll(',','.'))??0,leadTimeSeconds:double.tryParse(_lead.text.replaceAll(',','.'))??0,valueAdd:_va)]);_process.clear();_ct.clear();_co.clear();_wip.clear();_lead.clear();}
  Future<void> _save() async {final m=VsmMap(state:_state,id:DateTime.now().microsecondsSinceEpoch.toString(),name:_name.text.trim().isEmpty?'VSM':_name.text.trim(),customerDemandPerDay:double.tryParse(_demand.text.replaceAll(',','.'))??0,processes:List.unmodifiable(_processes));final n=[..._maps,m];await _storage.save(n);await AppHistoryStorage().add(HistoryEntry(module:'VSM',title:m.name,subtitle:'VA/Lead ${m.vaRatio.toStringAsFixed(1)}%'));if(mounted)setState(()=>_maps=n);}
  @override void dispose(){for(final c in [_name,_demand,_process,_ct,_co,_uptime,_wip,_lead])c.dispose();super.dispose();}
  @override Widget build(BuildContext context){final temp=VsmMap(id:'',name:'',processes:_processes);return Scaffold(appBar:AppBar(title:const Text('VSM')),body:ListView(padding:const EdgeInsets.all(16),children:[TextField(controller:_name,decoration:const InputDecoration(labelText:'Map nomi')),TextField(controller:_demand,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Customer demand / day')),SegmentedButton<String>(segments: const [ButtonSegment(value:'Current State',label:Text('Current State')),ButtonSegment(value:'Future State',label:Text('Future State'))],selected:{_state},onSelectionChanged:(v)=>setState(()=>_state=v.first)),const SizedBox(height:12),Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[Text('Process',style:Theme.of(context).textTheme.titleMedium),TextField(controller:_process,decoration:const InputDecoration(labelText:'Process nomi')),Row(children:[Expanded(child:TextField(controller:_ct,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'CT (s)'))),const SizedBox(width:8),Expanded(child:TextField(controller:_co,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'C/O (s)'))),const SizedBox(width:8),Expanded(child:TextField(controller:_uptime,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Uptime %')))]),Row(children:[Expanded(child:TextField(controller:_wip,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'WIP'))),const SizedBox(width:8),Expanded(child:TextField(controller:_lead,keyboardType:TextInputType.number,decoration:const InputDecoration(labelText:'Lead Time (s)'))),Checkbox(value:_va,onChanged:(v)=>setState(()=>_va=v??true)),const Text('VA'),IconButton(onPressed:_add,icon:const Icon(Icons.add_circle))]),..._processes.map((p)=>ListTile(dense:true,leading:CircleAvatar(child:Text('${p.sequence}')),title:Text(p.name),subtitle:Text('CT ${p.cycleTimeSeconds}s • Lead ${p.leadTimeSeconds}s • ${p.valueAdd?'VA':'NVA'}'),trailing:IconButton(icon:const Icon(Icons.delete_outline),onPressed:()=>setState(()=>_processes=_processes.where((x)=>x.id!=p.id).toList()))) ]))),Wrap(spacing:10,children:[Chip(label:Text('CT ${temp.totalCycleTime.toStringAsFixed(1)} s')),Chip(label:Text('Lead ${temp.totalLeadTime.toStringAsFixed(1)} s')),Chip(label:Text('VA ${temp.valueAddTime.toStringAsFixed(1)} s')),Chip(label:Text('VA ratio ${temp.vaRatio.toStringAsFixed(1)}%'))]),const SizedBox(height:12),Row(children:[Expanded(child:FilledButton.icon(onPressed:_save,icon:const Icon(Icons.save_outlined),label:const Text('Saqlash'))),const SizedBox(width:10),OutlinedButton.icon(onPressed:()=>VsmExcel().importMap().then((m){if(m!=null&&mounted)setState(()=>_processes=m.processes);}),icon:const Icon(Icons.file_open_outlined),label:const Text('Import')),const SizedBox(width:10),OutlinedButton.icon(onPressed:_maps.isEmpty?null:()=>VsmExcel().export(_maps.last),icon:const Icon(Icons.table_view),label:const Text('Excel'))]),const SizedBox(height:24),Text('Saqlangan VSM',style:Theme.of(context).textTheme.titleLarge),..._maps.reversed.map((m)=>Card(child:ListTile(title:Text(m.name),subtitle:Text('${m.processes.length} process • VA ratio ${m.vaRatio.toStringAsFixed(1)}%'),trailing:IconButton(icon:const Icon(Icons.file_download_outlined),onPressed:()=>VsmExcel().export(m)))))]));}
}
